            + N' ON ' + @QualifiedTableName + N' (' + @StatsColumns + N')'
            + CASE WHEN @StatsHasFilter = 1 THEN N' WHERE ' + @StatsFilter ELSE N'' END
            + CASE WHEN @StatsOptions = N'' THEN N'' ELSE N' WITH ' + @StatsOptions END
