        END;

        FETCH NEXT FROM alter_cursor INTO @ColumnName, @TargetIsNullable, @TypeDeclaration, @WasRowGuidCol;
    END;

    CLOSE alter_cursor;
    DEALLOCATE alter_cursor;

    DECLARE create_cursor CURSOR LOCAL FAST_FORWARD FOR
