    SET @Message = N'CYB-361 ObjectSecurity migration blocked: '
        + CONVERT(NVARCHAR(30), @NullUserIdCount)
        + N' row(s) have NULL UserId. No identity value will be guessed.';
    THROW 60361, @Message, 1;
