    FROM [SCore].[Identities] AS i
    WHERE i.[ID] = os.[UserId]
);

IF @OrphanUserIdCount > 0
BEGIN
    SET @Message = N'CYB-361 ObjectSecurity migration blocked: '
        + CONVERT(NVARCHAR(30), @OrphanUserIdCount)
