/* Deploy Function SCore.ObjectSecurityForUser using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SCore.ObjectSecurityForUser.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SCore.ObjectSecurityForUser
    Source schema hash : 64A75CBE67CBCBB74253F00B3CBB8B4C8EBFD990A0D8536F4BC56E2462DF75BE
    Definition SHA-256 : D37C0E1780C1D9625EE3718A52E9CE05E3289EB03B981405E090C037CD537FCF

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SCore].[ObjectSecurityForUser]
	(
		@ObjectGuid UNIQUEIDENTIFIER,
		@UserId		INT
	)
RETURNS TABLE
                           --WITH SCHEMABINDING
AS
	RETURN
	SELECT
			@ObjectGuid AS ObjectGuid,
			CAST(CASE
					-- AUDIT group precedence: audit members can always read
					WHEN EXISTS
						(
							SELECT 1 
							FROM SCore.Identities root_hobt
							LEFT JOIN SCore.UserGroups ug ON (root_hobt.ID = ug.IdentityID)
							LEFT JOIN SCore.Groups g ON (g.ID = ug.GroupID)
							WHERE 
									(root_hobt.ID = @UserId)
								AND (g.Code = N'AUDIT')
								AND (ug.RowStatus NOT IN (0,254))
						) THEN
						1
					WHEN EXISTS
						(
							SELECT
									1
							FROM
									SCore.ExpandedObjectSecurityForUser(@ObjectGuid, @UserId) os1
							WHERE
									os1.DenyRead > 0
						) THEN
						0
					WHEN EXISTS
						(
							SELECT
									1
							FROM
									SCore.ExpandedObjectSecurityForUser(@ObjectGuid, @UserId) os1
							WHERE
									os1.CanRead > 0
						) THEN
						1
					ELSE
					(CASE
							WHEN ISNULL(os2.HasSecurity, 0) = 0 THEN
								1
							ELSE
							0
					END
					)
			END AS BIT) AS CanRead,
			CAST(CASE
					-- AUDIT group precedence: audit members can never write, regardless of any other group
					WHEN EXISTS
						(
							SELECT 1 
							FROM SCore.Identities root_hobt
							LEFT JOIN SCore.UserGroups ug ON (root_hobt.ID = ug.IdentityID)
							LEFT JOIN SCore.Groups g ON (g.ID = ug.GroupID)
							WHERE 
									(root_hobt.ID = @UserId)
								AND (g.Code = N'AUDIT')
								AND (ug.RowStatus NOT IN (0,254))
						) THEN
						0
					WHEN EXISTS
						(
							SELECT
									1
							FROM
									SCore.ExpandedObjectSecurityForUser(@ObjectGuid, @UserId) os1
							WHERE
									os1.DenyWrite > 0
						) THEN
						0
					WHEN EXISTS
						(
							SELECT
									1
							FROM
									SCore.ExpandedObjectSecurityForUser(@ObjectGuid, @UserId) os1
							WHERE
									os1.CanWrite > 0
						) THEN
						1
					ELSE
					(CASE
							WHEN ISNULL(os2.HasSecurity, 0) = 0 THEN
								1
							ELSE
							0
					END
					)
			END AS BIT) AS CanWrite
	FROM
			[SCore].[Identities] i
	OUTER APPLY
			(
				SELECT
						1 HasSecurity
				WHERE
						(EXISTS
						(
							SELECT
									1
							FROM
									SCore.ObjectSecurity os3
							WHERE
									(os3.ObjectGuid = @ObjectGuid)
									AND (os3.RowStatus NOT IN (0, 254))
						)
						)
			) AS os2
	WHERE
			(i.ID = @UserId)
GO

GO

