/* Deploy Function SJob.tvf_SubcontractorInvoices using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SJob.tvf_SubcontractorInvoices.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SJob.tvf_SubcontractorInvoices
    Source schema hash : D8E7993BD533EA836D3493E16641EBBD5D6E171D87E1252077B3A018A85ADB3C
    Definition SHA-256 : E40A67A02763B05A5098B69D21CC7795E8BB694EAF990BB6FEB52EFE8210298A

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SJob].[tvf_SubcontractorInvoices]
(
	@UserId INT,
	@ParentGuid UNIQUEIDENTIFIER
)
RETURNS TABLE
AS
RETURN
(
	WITH VisibleInvoices AS
	(
		SELECT  
				si.ID,
				si.Guid,
				si.RowVersion,
				si.RowStatus,
				CASE 
					WHEN (si.SubContractorName = N'' AND si.SubContractorId <> -1 ) THEN acc.Name ELSE si.SubContractorName
				END AS SubContractorName,
				--si.SubContractorName,
				si.DescriptionOfWork,
				si.InvoiceDate,
				si.ValueWithVAT,
				si.ValueWithoutVAT,
				CAST(NULL AS DECIMAL(18,2)) AS NetFee,
				CAST(NULL AS DECIMAL(18,2)) AS Margin
		FROM    SJob.SubContractorInvoices AS si
		JOIN    SJob.Jobs AS j 
				ON j.ID = si.JobId
		JOIN SCrm.Accounts acc ON (acc.ID = si.SubContractorId)
		WHERE   si.RowStatus NOT IN (0, 254)
			AND si.ID > 0
			AND j.Guid = @ParentGuid
			AND EXISTS
			(
				SELECT 1
				FROM SCore.ObjectSecurityForUser_CanRead (si.Guid, @UserId)
			)
	)

	/* Detail rows */
	SELECT
			ID,
			Guid,
			RowVersion,
			RowStatus,
			SubContractorName,
			DescriptionOfWork,
			InvoiceDate,
			ValueWithVAT,
			ValueWithoutVAT,
			NetFee,
			Margin
	FROM VisibleInvoices

	UNION ALL

	/* Total row */
	SELECT
			-1 AS ID,
			MIN(vi.Guid) AS Guid,
			NULL AS RowVersion,
			1 AS RowStatus,
			N'Total' AS SubContractorName,
			N'' AS DescriptionOfWork,
			NULL AS InvoiceDate,

			/* Total subcontractor cost */
			SUM(vi.ValueWithVAT) AS ValueWithVAT,
			SUM(vi.ValueWithoutVAT) AS ValueWithoutVAT,

			/* Adjusted net fee (Total ex. Fee Cap) */
			MAX(jfd.Agreed) + SUM(vi.ValueWithoutVAT) AS NetFee,

			/* Remaining margin */
			MAX(jfd.Remaining) - SUM(vi.ValueWithoutVAT) AS Margin
	FROM VisibleInvoices vi
	JOIN SJob.Jobs j
		ON j.Guid = @ParentGuid
	JOIN SJob.Job_FeeDrawdown jfd
		ON jfd.JobId = j.ID
		AND jfd.StageId = -2   -- Total (ex. Fee Cap)
);
GO

GO

/* Deploy Function SOffice.tvf_FrequentFilingRecords using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SOffice.tvf_FrequentFilingRecords.sql */
/*
    CymBuild generated canonical schema source.
