/* Deploy View SCore.UserUsageLast7Days using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Views\SCore.UserUsageLast7Days.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : View SCore.UserUsageLast7Days
    Source schema hash : 48A663DDDD8909903158428D60C514B2B2CCA6C37BD9F4C356860EFEE5924E01
    Definition SHA-256 : 503FD0B87F11A44E396D983BA5567490D380F14A1DF5C8D95599C771A9FA4049

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER VIEW [SCore].[UserUsageLast7Days]
AS
WITH [ReportingPeriod] AS
(
    SELECT
        DATEADD(DAY, -6, CONVERT(date, GETDATE()))  AS [CurrentPeriodStart],
        DATEADD(DAY,  1, CONVERT(date, GETDATE()))  AS [CurrentPeriodEnd],
        DATEADD(DAY, -13, CONVERT(date, GETDATE())) AS [PreviousPeriodStart]
),
[UserUsage] AS
(
    SELECT
        sul.[UserGuid],

        COUNT
        (
            CASE
                WHEN sul.[Accessed] >= rp.[CurrentPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
                THEN 1
            END
        ) AS [UsageCountLast7Days],

        COUNT
        (
            CASE
                WHEN sul.[Accessed] >= rp.[PreviousPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodStart]
                THEN 1
            END
        ) AS [UsageCountPrevious7Days],

        COUNT
        (
            DISTINCT CASE
                WHEN sul.[Accessed] >= rp.[CurrentPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
                THEN CONVERT(date, sul.[Accessed])
            END
        ) AS [ActiveDaysLast7Days],

        COUNT
        (
            DISTINCT CASE
                WHEN sul.[Accessed] >= rp.[CurrentPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
                THEN sul.[FeatureName]
            END
        ) AS [FeaturesUsedLast7Days],

        MIN
        (
            CASE
                WHEN sul.[Accessed] >= rp.[CurrentPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
                THEN sul.[Accessed]
            END
        ) AS [FirstAccessedLast7Days],

        MAX
        (
            CASE
                WHEN sul.[Accessed] >= rp.[CurrentPeriodStart]
                 AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
                THEN sul.[Accessed]
            END
        ) AS [LastAccessedLast7Days]
    FROM [SCore].[SystemUsageLog] AS sul
    CROSS JOIN [ReportingPeriod] AS rp
    WHERE sul.[Accessed] >= rp.[PreviousPeriodStart]
      AND sul.[Accessed] <  rp.[CurrentPeriodEnd]
    GROUP BY
        sul.[UserGuid]
)
SELECT
    i.[FullName]                                      AS [UserName],
    i.[Guid]                                          AS [UserGuid],
    uu.[UsageCountLast7Days],
    uu.[ActiveDaysLast7Days],
    uu.[FeaturesUsedLast7Days],
    CONVERT
    (
        decimal(18, 2),
        uu.[UsageCountLast7Days] / 7.0
    )                                                 AS [AverageDailyUsage],
    uu.[FirstAccessedLast7Days],
    uu.[LastAccessedLast7Days],
    uu.[UsageCountPrevious7Days],
    CONVERT
    (
        decimal(18, 2),
        CASE
            WHEN uu.[UsageCountPrevious7Days] = 0
                THEN NULL
            ELSE
                (
                    (uu.[UsageCountLast7Days]
                     - uu.[UsageCountPrevious7Days]) * 100.0
                ) / uu.[UsageCountPrevious7Days]
        END
    )                                                 AS [UsageChangePercentage],
    CASE
        WHEN uu.[UsageCountPrevious7Days] = 0
         AND uu.[UsageCountLast7Days] > 0
            THEN N'New usage'
        WHEN uu.[UsageCountLast7Days]
             > uu.[UsageCountPrevious7Days]
            THEN N'Increased'
        WHEN uu.[UsageCountLast7Days]
             < uu.[UsageCountPrevious7Days]
            THEN N'Decreased'
        ELSE N'No change'
    END                                               AS [UsageTrend]
FROM [UserUsage] AS uu
JOIN [SCore].[Identities] AS i
    ON i.[Guid] = uu.[UserGuid]
WHERE uu.[UsageCountLast7Days] > 0;
GO

GO

/* Deploy View SFin.vw_InvoiceAutomation_BlockingDiagnostics using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Views\SFin.vw_InvoiceAutomation_BlockingDiagnostics.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : View SFin.vw_InvoiceAutomation_BlockingDiagnostics
    Source schema hash : E862254CB72ECD6BE1C72F0FF416338E5EB1193444CA004DE99DCCC707520221
    Definition SHA-256 : 19552FA29FCB0BDED794ECBF7CFEFD2E77742CF7E1A81248E578D6CE6AC45BE7

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
    Permanent correction:
    - InvoiceProcessingMode: 0 = Automated, 1 = Manual, 2 = Paused.
    - ManualInvoicingEnabled is retained in the output for compatibility, but it
      is no longer used as the authoritative automation gate.
    - CannotBeInvoiced is also honoured before an automated request is created;
      downstream request views already treat this flag as non-invoiceable.
*/
CREATE OR ALTER VIEW [SFin].[vw_InvoiceAutomation_BlockingDiagnostics]
AS
WITH ScheduleJobScope AS
(
    SELECT DISTINCT
          qi.ID                AS QuoteItemId
        , qi.Guid              AS QuoteItemGuid
        , qi.InvoicingSchedule AS InvoiceScheduleId
        , sch.Guid             AS InvoiceScheduleGuid
        , qi.CreatedJobId      AS JobId
    FROM SSop.QuoteItems AS qi
    INNER JOIN SFin.InvoiceSchedules AS sch
        ON sch.ID = qi.InvoicingSchedule
    WHERE qi.RowStatus NOT IN (0, 254)
      AND sch.RowStatus NOT IN (0, 254)
      AND qi.CreatedJobId NOT IN (-1, 0)
      AND qi.InvoicingSchedule NOT IN (-1, 0)
),
BlockingResolution AS
(
    SELECT
          sjs.QuoteItemId
        , sjs.QuoteItemGuid
        , sjs.InvoiceScheduleId
        , sjs.InvoiceScheduleGuid
        , sjs.JobId
        , j.ManualInvoicingEnabled
        , a.ID AS FinanceAccountId
        , acs.IsHold AS AccountIsOnHold
        , acs.Name AS AccountStatusName
        , CAST
          (
              CASE
                  WHEN j.InvoiceProcessingMode IN (1, 2) THEN 1
                  WHEN ISNULL(j.CannotBeInvoiced, 0) = 1 THEN 1
                  WHEN ISNULL(acs.IsHold, 0) = 1 THEN 1
                  ELSE 0
              END
              AS BIT
          ) AS IsBlocked
        , CASE
              WHEN j.InvoiceProcessingMode = 1 THEN N'MANUAL_JOB'
              WHEN j.InvoiceProcessingMode = 2 THEN N'PAUSED_JOB'
              WHEN ISNULL(j.CannotBeInvoiced, 0) = 1 THEN N'JOB_CANNOT_BE_INVOICED'
              WHEN ISNULL(acs.IsHold, 0) = 1 THEN N'ACCOUNT_ON_HOLD'
              ELSE N'NONE'
          END AS BlockedReasonCode
        , CASE
              WHEN j.InvoiceProcessingMode = 1 THEN N'Job is explicitly set to Manual invoicing'
              WHEN j.InvoiceProcessingMode = 2 THEN N'Job invoicing is paused'
              WHEN ISNULL(j.CannotBeInvoiced, 0) = 1
                  THEN CONVERT
                  (
                      NVARCHAR(200),
                      COALESCE(NULLIF(j.CannotBeInvoicedReason, N''), N'Job is marked as unable to be invoiced')
                  )
              WHEN ISNULL(acs.IsHold, 0) = 1 THEN N'Finance account is on hold'
              ELSE N'Not blocked'
          END AS BlockedReason
        , CASE
              WHEN j.InvoiceProcessingMode IN (1, 2) THEN N'Job'
              WHEN ISNULL(j.CannotBeInvoiced, 0) = 1 THEN N'Job'
              WHEN ISNULL(acs.IsHold, 0) = 1 THEN N'Account'
              ELSE N'None'
          END AS BlockingSource
    FROM ScheduleJobScope AS sjs
    INNER JOIN SJob.Jobs AS j
        ON j.ID = sjs.JobId
       AND j.RowStatus NOT IN (0, 254)
    LEFT JOIN SCrm.Accounts AS a
        ON a.ID = j.FinanceAccountID
    LEFT JOIN SCrm.AccountStatus AS acs
        ON acs.ID = a.AccountStatusID
)
SELECT
      InvoiceScheduleId
    , InvoiceScheduleGuid
    , JobId
    , QuoteItemId
    , QuoteItemGuid
    , IsBlocked
    , BlockedReasonCode
    , BlockedReason
    , ManualInvoicingEnabled
    , AccountIsOnHold
    , FinanceAccountId
    , AccountStatusName
    , BlockingSource
FROM BlockingResolution;
