    Object             : StoredProcedure SMigration.MetadataEntityTypeScope_Set
    Source schema hash : B2D8D1F5455342D573F8664BAACF69750F5BC136B4AA56D1FB1809C9A9A5A0D8
    Definition SHA-256 : 5B5257F1E348728F97B3503BA0514214110BEEC41EB11A818F3DA9955DD00F20

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SMigration].[MetadataEntityTypeScope_Set]
(
    @EntityTypeGuid UNIQUEIDENTIFIER,
    @IsMetaData BIT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SCore.EntityTypes AS et
        WHERE et.Guid = @EntityTypeGuid
          AND et.RowStatus NOT IN (0,254)
    )
    BEGIN
        ;THROW 52200, 'The EntityType was not found or is inactive.', 1;
    END;

    UPDATE SCore.EntityTypes
    SET IsMetaData = ISNULL(@IsMetaData, 0)
    WHERE Guid = @EntityTypeGuid
      AND RowStatus NOT IN (0,254)
      AND IsMetaData <> ISNULL(@IsMetaData, 0);

    SELECT CONVERT(INT, @@ROWCOUNT) AS UpdatedCount;
END;
GO

