/* Deploy StoredProcedure SMigration.MetadataRegistry_SyncFromEntityTypes using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataRegistry_SyncFromEntityTypes.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SMigration.MetadataRegistry_SyncFromEntityTypes
    Source schema hash : C411DA496EAB338773BDA68A8D4C0B27E45F9FC3262D006C7B2ACDCA76EBBCCA
    Definition SHA-256 : 6838F66B23E59B7CC31D659F0F1B8ABEE53A82A88C0EE553D376C425370BD88F

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SMigration].[MetadataRegistry_SyncFromEntityTypes]
(
    @SourceDatabaseName SYSNAME = NULL,
    @TargetDatabaseName SYSNAME = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @SourceDb SYSNAME = NULLIF(@SourceDatabaseName, N''),
        @TargetDb SYSNAME = ISNULL(NULLIF(@TargetDatabaseName, N''), DB_NAME()),
        @ControlDb SYSNAME,
        @ControlSourceName NVARCHAR(20),
        @Sql NVARCHAR(MAX);

    /*
        R16C behaviour:
        - When a source database is supplied, source EntityTypes are authoritative
          for what is metadata in the migration run.
        - When no source database is supplied, fall back to the target/current database
          so maintenance calls still have a deterministic control database.
        - Registry rows backed by an EntityType main HoBT in the control database are
          enabled only when that EntityType has IsMetaData = 1.
        - Existing curated registry rows that are not backed by a controllable EntityType
          are left untouched.
    */
    SET @ControlDb = CASE
        WHEN @SourceDb IS NOT NULL AND DB_ID(@SourceDb) IS NOT NULL THEN @SourceDb
        WHEN @TargetDb IS NOT NULL AND DB_ID(@TargetDb) IS NOT NULL THEN @TargetDb
        ELSE DB_NAME()
    END;

    SET @ControlSourceName = CASE
        WHEN @SourceDb IS NOT NULL AND DB_ID(@SourceDb) IS NOT NULL THEN N'Source'
        WHEN @TargetDb IS NOT NULL AND DB_ID(@TargetDb) IS NOT NULL THEN N'Target'
        ELSE N'Current'
    END;

    IF OBJECT_ID(N'tempdb..#MetadataRegistryEntityTypeControlledTables') IS NOT NULL
        DROP TABLE #MetadataRegistryEntityTypeControlledTables;

    IF OBJECT_ID(N'tempdb..#MetadataRegistryEntityTypeCandidates') IS NOT NULL
        DROP TABLE #MetadataRegistryEntityTypeCandidates;

    CREATE TABLE #MetadataRegistryEntityTypeControlledTables
    (
        SchemaName SYSNAME NOT NULL,
        TableName SYSNAME NOT NULL,
        IsMetaData BIT NOT NULL,
        SourceName NVARCHAR(20) NOT NULL
    );

    CREATE TABLE #MetadataRegistryEntityTypeCandidates
    (
        SchemaName SYSNAME NOT NULL,
        TableName SYSNAME NOT NULL,
        SourceName NVARCHAR(20) NOT NULL
    );

    IF @ControlDb IS NOT NULL AND DB_ID(@ControlDb) IS NOT NULL
    BEGIN
        SET @Sql = N'
INSERT INTO #MetadataRegistryEntityTypeControlledTables
(
    SchemaName,
    TableName,
    IsMetaData,
    SourceName
)
SELECT DISTINCT
    CONVERT(SYSNAME, eh.SchemaName) AS SchemaName,
    CONVERT(SYSNAME, eh.ObjectName) AS TableName,
    CONVERT(BIT, ISNULL(et.IsMetaData, 0)) AS IsMetaData,
    @ControlSourceName AS SourceName
FROM ' + QUOTENAME(@ControlDb) + N'.SCore.EntityTypes AS et
INNER JOIN ' + QUOTENAME(@ControlDb) + N'.SCore.EntityHobts AS eh
    ON eh.EntityTypeID = et.ID
   AND eh.RowStatus NOT IN (0,254)
WHERE et.RowStatus NOT IN (0,254)
  AND ISNULL(eh.IsMainHoBT, 0) = 1
  AND NULLIF(eh.SchemaName, N'''') IS NOT NULL
  AND NULLIF(eh.ObjectName, N'''') IS NOT NULL;

INSERT INTO #MetadataRegistryEntityTypeCandidates
(
    SchemaName,
    TableName,
    SourceName
)
SELECT DISTINCT
    controlled.SchemaName,
    controlled.TableName,
    controlled.SourceName
FROM #MetadataRegistryEntityTypeControlledTables AS controlled
WHERE controlled.IsMetaData = 1;';

        EXEC sys.sp_executesql
            @Sql,
            N'@ControlSourceName NVARCHAR(20)',
            @ControlSourceName = @ControlSourceName;
    END;

    ;WITH ControlledTables AS
    (
        SELECT
            controlled.SchemaName,
            controlled.TableName,
            MAX(CONVERT(INT, controlled.IsMetaData)) AS IsMetaData
        FROM #MetadataRegistryEntityTypeControlledTables AS controlled
        WHERE NULLIF(controlled.SchemaName, N'') IS NOT NULL
          AND NULLIF(controlled.TableName, N'') IS NOT NULL
        GROUP BY
            controlled.SchemaName,
            controlled.TableName
    )
    UPDATE target
    SET
        target.IsEnabled = 0
    FROM SMigration.Metadata_TableRegistry AS target
    INNER JOIN ControlledTables AS controlled
        ON controlled.SchemaName = target.SchemaName
       AND controlled.TableName = target.TableName
    WHERE controlled.IsMetaData = 0
      AND target.RowStatus NOT IN (0,254)
      AND target.IsEnabled = 1;

    ;WITH DistinctCandidates AS
    (
        SELECT
            c.SchemaName,
            c.TableName,
            MIN(c.SourceName) AS FirstSeenIn,
            ROW_NUMBER() OVER (ORDER BY c.SchemaName, c.TableName) AS CandidateOrder
        FROM #MetadataRegistryEntityTypeCandidates AS c
        WHERE NULLIF(c.SchemaName, N'') IS NOT NULL
          AND NULLIF(c.TableName, N'') IS NOT NULL
        GROUP BY
            c.SchemaName,
            c.TableName
    ),
    CandidateValues AS
    (
        SELECT
            CONVERT(UNIQUEIDENTIFIER, SUBSTRING(HASHBYTES('SHA2_256', CONVERT(VARBINARY(MAX), UPPER(CONCAT(N'SMigration.Metadata_TableRegistry|', dc.SchemaName, N'.', dc.TableName)))), 1, 16)) AS RegistryGuid,
            dc.SchemaName,
            dc.TableName,
            CONVERT(INT, 10000 + dc.CandidateOrder) AS ApplyOrder
        FROM DistinctCandidates AS dc
    )
    UPDATE target
    SET
        target.RowStatus = 1,
        target.IsEnabled = 1,
        target.GuidColumnName = CASE WHEN NULLIF(target.GuidColumnName, N'') IS NULL THEN N'Guid' ELSE target.GuidColumnName END,
        target.PrimaryKeyColumnName = CASE WHEN NULLIF(target.PrimaryKeyColumnName, N'') IS NULL THEN N'ID' ELSE target.PrimaryKeyColumnName END
    FROM SMigration.Metadata_TableRegistry AS target
    INNER JOIN CandidateValues AS source
        ON source.SchemaName = target.SchemaName
       AND source.TableName = target.TableName;

    ;WITH DistinctCandidates AS
    (
        SELECT
            c.SchemaName,
            c.TableName,
            ROW_NUMBER() OVER (ORDER BY c.SchemaName, c.TableName) AS CandidateOrder
        FROM #MetadataRegistryEntityTypeCandidates AS c
        WHERE NULLIF(c.SchemaName, N'') IS NOT NULL
          AND NULLIF(c.TableName, N'') IS NOT NULL
        GROUP BY
            c.SchemaName,
            c.TableName
    ),
    CandidateValues AS
    (
        SELECT
            CONVERT(UNIQUEIDENTIFIER, SUBSTRING(HASHBYTES('SHA2_256', CONVERT(VARBINARY(MAX), UPPER(CONCAT(N'SMigration.Metadata_TableRegistry|', dc.SchemaName, N'.', dc.TableName)))), 1, 16)) AS RegistryGuid,
            dc.SchemaName,
            dc.TableName,
            CONVERT(INT, 10000 + dc.CandidateOrder) AS ApplyOrder
        FROM DistinctCandidates AS dc
    )
    INSERT INTO SMigration.Metadata_TableRegistry
    (
        Guid,
        RowStatus,
        SchemaName,
        TableName,
        GuidColumnName,
        PrimaryKeyColumnName,
        ApplyOrder,
        IsEnabled,
        IsDataObjectBacked,
        IsRetirable,
        IsEnvironmentSpecific,
        NaturalKeyJson,
        ParentDependencyJson,
        CreatedOnUtc
    )
    SELECT
        source.RegistryGuid,
        1,
        source.SchemaName,
        source.TableName,
        N'Guid',
        N'ID',
        source.ApplyOrder,
        1,
        1,
        1,
        0,
        N'[]',
        N'[]',
        SYSUTCDATETIME()
    FROM CandidateValues AS source
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM SMigration.Metadata_TableRegistry AS target
        WHERE target.SchemaName = source.SchemaName
          AND target.TableName = source.TableName
    )
      AND NOT EXISTS
    (
        SELECT 1
        FROM SMigration.Metadata_TableRegistry AS targetGuid
        WHERE targetGuid.Guid = source.RegistryGuid
    );

    DECLARE
        @RegistryGuid UNIQUEIDENTIFIER,
        @SchemaName SYSNAME,
        @TableName SYSNAME;

    DECLARE registry_do_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            tr.Guid,
            tr.SchemaName,
            tr.TableName
        FROM SMigration.Metadata_TableRegistry AS tr
        INNER JOIN
        (
            SELECT
                c.SchemaName,
                c.TableName
            FROM #MetadataRegistryEntityTypeCandidates AS c
            GROUP BY
                c.SchemaName,
                c.TableName
        ) AS c
            ON c.SchemaName = tr.SchemaName
           AND c.TableName = tr.TableName
        WHERE tr.RowStatus NOT IN (0,254);

    OPEN registry_do_cursor;

    FETCH NEXT FROM registry_do_cursor INTO @RegistryGuid, @SchemaName, @TableName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @RegistryGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Metadata_TableRegistry';

        FETCH NEXT FROM registry_do_cursor INTO @RegistryGuid, @SchemaName, @TableName;
    END;

    CLOSE registry_do_cursor;
    DEALLOCATE registry_do_cursor;

    SELECT
        COUNT_BIG(1) AS CandidateCount,
        @ControlDb AS ControlDatabaseName,
        @ControlSourceName AS ControlSourceName
    FROM
    (
        SELECT
            c.SchemaName,
            c.TableName
        FROM #MetadataRegistryEntityTypeCandidates AS c
        GROUP BY
            c.SchemaName,
            c.TableName
    ) AS groupedCandidates;
END;
GO

GO

/* Deploy StoredProcedure SMigration.MetadataRunSelection_AddDependencies using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataRunSelection_AddDependencies.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[MetadataRunSelection_AddDependencies]')
GO

/*
    CYB-564: when rows are selected for apply, also select the rows they need or that belong
    to them, so a selection cannot leave a new child without its new parent (seen live: HoBT
    SJob.FeeAmendmentChase selected without its new EntityType 'Fee Amendment Chase', which
    failed Apply with a raw NOT NULL error on EntityHobts.EntityTypeID).

    @SeedJson is the rows the user just selected:
    [{"SchemaName":"SCore","TableName":"EntityHobts","SourceRowGuid":"..."}].
    Relationships are the declared single-column foreign keys between registered tables (the
    same set MetadataStage_NormaliseDifferences, MetadataValidate_Run and MetadataApply_Run use),
    matched through each staged row's SourceRowId.

      1. Down: staged Insert/Update rows that reference a seed row, then rows that reference
         those, and so on. Only Insert/Update rows are followed.
      2. Up: for every seed row and every row from step 1, new (Insert) parents, recursively.
         An Update/NoChange parent already exists in the target, and a parent with an Identity
         Map override resolves to its mapped target row, so neither is needed.
         Parents added in step 2 do not pull in their own children; otherwise selecting one HoBT
         would select every other HoBT and property of its EntityType.

    Ignored rows are never selected. Added rows are recorded with SelectionSource
    N'Dependency'. Unselecting a row does not cascade; MetadataValidate_Run and
    MetadataApply_Run block a selection that is left without a required parent.
*/
CREATE OR ALTER PROCEDURE [SMigration].[MetadataRunSelection_AddDependencies]
(
    @RunGuid UNIQUEIDENTIFIER,
    @SeedJson NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @TargetDatabaseName SYSNAME,
        @AddedCount INT = 0,
        @SelectionGuid UNIQUEIDENTIFIER,
        @RegistryGuid UNIQUEIDENTIFIER,
        @SourceRowGuid UNIQUEIDENTIFIER,
        @DifferenceType NVARCHAR(30);

    SELECT
        @TargetDatabaseName = run.TargetDatabaseName
    FROM SMigration.Metadata_Run AS run
    WHERE run.Guid = @RunGuid
      AND run.RowStatus NOT IN (0,254);

    IF @TargetDatabaseName IS NULL
        THROW 52103, 'Metadata run was not found or is inactive.', 1;

    CREATE TABLE #Rows
    (
        StagedRowId BIGINT NOT NULL PRIMARY KEY,
        RegistryGuid UNIQUEIDENTIFIER NOT NULL,
        SourceRowGuid UNIQUEIDENTIFIER NOT NULL,
        SourceRowId BIGINT NULL,
        DifferenceType NVARCHAR(30) NOT NULL,
        IsSelectable BIT NOT NULL,
        HasOverride BIT NOT NULL
    );

    INSERT INTO #Rows
    (
        StagedRowId,
        RegistryGuid,
        SourceRowGuid,
        SourceRowId,
        DifferenceType,
        IsSelectable,
        HasOverride
    )
    SELECT
        sr.ID,
        sr.RegistryGuid,
        sr.SourceRowGuid,
        sr.SourceRowId,
        sr.DifferenceType,
        CASE
            WHEN sr.DifferenceType IN (N'Insert', N'Update')
                 AND NOT EXISTS
                 (
                     SELECT 1
                     FROM SMigration.Metadata_IgnoredRecords AS ignored
                     WHERE ignored.DatabaseName = @TargetDatabaseName
                       AND ignored.RegistryGuid = sr.RegistryGuid
                       AND ignored.SourceRowGuid = sr.SourceRowGuid
                       AND ignored.RowStatus NOT IN (0,254)
                 ) THEN 1
            ELSE 0
        END,
        CASE
            WHEN EXISTS
            (
                SELECT 1
                FROM SMigration.Metadata_IdentityMapOverrides AS identityOverride
                WHERE identityOverride.DatabaseName = @TargetDatabaseName
                  AND identityOverride.RegistryGuid = sr.RegistryGuid
                  AND identityOverride.SourceRowGuid = sr.SourceRowGuid
                  AND identityOverride.RowStatus NOT IN (0,254)
            ) THEN 1
            ELSE 0
        END
    FROM SMigration.Metadata_StagedRows AS sr
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.SourceRowGuid IS NOT NULL;

    CREATE INDEX IX_Rows_Registry_SourceRowId ON #Rows (RegistryGuid, SourceRowId);

    -- Each step below is materialised on purpose. Joining staged rows to their parents directly
    -- on a JSON_VALUE of the child payload let the optimiser re-parse payloads for every
    -- candidate pair, and a ~14,000-row run did not finish within the 300 second timeout.
    CREATE TABLE #ForeignKeys
    (
        ChildRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        ColumnName SYSNAME NOT NULL,
        RefRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        PRIMARY KEY CLUSTERED (ChildRegistryGuid, ColumnName)
    );

    ;WITH RegisteredForeignKeys AS
    (
        SELECT
            childTr.Guid AS ChildRegistryGuid,
            pc.name AS ColumnName,
            refTr.Guid AS RefRegistryGuid
        FROM SMigration.Metadata_TableRegistry AS childTr
        INNER JOIN sys.foreign_key_columns AS fkc
            ON fkc.parent_object_id = OBJECT_ID(QUOTENAME(childTr.SchemaName) + N'.' + QUOTENAME(childTr.TableName))
        INNER JOIN sys.columns AS pc
            ON pc.object_id = fkc.parent_object_id
           AND pc.column_id = fkc.parent_column_id
        INNER JOIN sys.tables AS rt
            ON rt.object_id = fkc.referenced_object_id
        INNER JOIN sys.schemas AS rs
            ON rs.schema_id = rt.schema_id
        INNER JOIN sys.columns AS rc
            ON rc.object_id = fkc.referenced_object_id
           AND rc.column_id = fkc.referenced_column_id
        INNER JOIN SMigration.Metadata_TableRegistry AS refTr
            ON refTr.SchemaName = rs.name
           AND refTr.TableName = rt.name
           AND refTr.RowStatus NOT IN (0,254)
           AND refTr.IsEnabled = 1
        WHERE childTr.RowStatus NOT IN (0,254)
          AND childTr.IsEnabled = 1
          AND pc.name <> N'RowStatus'
          AND rc.name = refTr.PrimaryKeyColumnName
          AND NOT EXISTS
          (
              SELECT 1
              FROM sys.foreign_key_columns AS otherColumn
              WHERE otherColumn.constraint_object_id = fkc.constraint_object_id
                AND otherColumn.constraint_column_id <> fkc.constraint_column_id
          )
    )
    INSERT INTO #ForeignKeys
    (
        ChildRegistryGuid,
        ColumnName,
        RefRegistryGuid
    )
    SELECT DISTINCT
        fk.ChildRegistryGuid,
        fk.ColumnName,
        fk.RefRegistryGuid
    FROM RegisteredForeignKeys AS fk;

    -- One JSON_VALUE per (staged row, foreign key column). JSON_VALUE returns at most 4000
    -- characters (NULL beyond that in lax mode), so the BIGINT conversion cannot raise 8152.
    CREATE TABLE #ChildReferences
    (
        ChildStagedRowId BIGINT NOT NULL,
        RefRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        ParentSourceRowId BIGINT NOT NULL
    );

    INSERT INTO #ChildReferences
    (
        ChildStagedRowId,
        RefRegistryGuid,
        ParentSourceRowId
    )
    SELECT
        refs.ChildStagedRowId,
        refs.RefRegistryGuid,
        refs.ParentSourceRowId
    FROM
    (
        SELECT
            child.ID AS ChildStagedRowId,
            fk.RefRegistryGuid,
            TRY_CONVERT(BIGINT, JSON_VALUE(child.SourcePayloadJson, N'$."' + fk.ColumnName + N'"')) AS ParentSourceRowId
        FROM SMigration.Metadata_StagedRows AS child
        INNER JOIN #ForeignKeys AS fk
            ON fk.ChildRegistryGuid = child.RegistryGuid
        WHERE child.RunGuid = @RunGuid
          AND child.RowStatus NOT IN (0,254)
    ) AS refs
    WHERE refs.ParentSourceRowId IS NOT NULL;

    CREATE INDEX IX_ChildReferences_Parent ON #ChildReferences (RefRegistryGuid, ParentSourceRowId);

    CREATE TABLE #Edges
    (
        ChildStagedRowId BIGINT NOT NULL,
        ParentStagedRowId BIGINT NOT NULL,
        PRIMARY KEY CLUSTERED (ChildStagedRowId, ParentStagedRowId)
    );

    INSERT INTO #Edges
    (
        ChildStagedRowId,
        ParentStagedRowId
    )
    SELECT DISTINCT
        cr.ChildStagedRowId,
        parent.StagedRowId
    FROM #ChildReferences AS cr
    INNER JOIN #Rows AS parent
        ON parent.RegistryGuid = cr.RefRegistryGuid
       AND parent.SourceRowId = cr.ParentSourceRowId
    WHERE parent.StagedRowId <> cr.ChildStagedRowId;

    CREATE INDEX IX_Edges_Parent ON #Edges (ParentStagedRowId, ChildStagedRowId);

    CREATE TABLE #Closure
    (
        StagedRowId BIGINT NOT NULL PRIMARY KEY,
        IsSeed BIT NOT NULL,
        IsDownward BIT NOT NULL
    );

    INSERT INTO #Closure
    (
        StagedRowId,
        IsSeed,
        IsDownward
    )
    SELECT DISTINCT
        r.StagedRowId,
        1,
        1
    FROM OPENJSON(@SeedJson)
        WITH
        (
            SchemaName SYSNAME '$.SchemaName',
            TableName SYSNAME '$.TableName',
            SourceRowGuid UNIQUEIDENTIFIER '$.SourceRowGuid'
        ) AS seed
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.SchemaName = seed.SchemaName
       AND tr.TableName = seed.TableName
       AND tr.RowStatus NOT IN (0,254)
    INNER JOIN #Rows AS r
        ON r.RegistryGuid = tr.Guid
       AND r.SourceRowGuid = seed.SourceRowGuid
    WHERE r.IsSelectable = 1;

    -- 1. Down: rows that reference a seed row or a row already found this way.
    WHILE 1 = 1
    BEGIN
        INSERT INTO #Closure
        (
            StagedRowId,
            IsSeed,
            IsDownward
        )
        SELECT DISTINCT
            e.ChildStagedRowId,
            0,
            1
        FROM #Closure AS c
        INNER JOIN #Edges AS e
            ON e.ParentStagedRowId = c.StagedRowId
        INNER JOIN #Rows AS childRow
            ON childRow.StagedRowId = e.ChildStagedRowId
        WHERE c.IsDownward = 1
          AND childRow.IsSelectable = 1
          AND NOT EXISTS (SELECT 1 FROM #Closure AS existing WHERE existing.StagedRowId = e.ChildStagedRowId);

        IF @@ROWCOUNT = 0 BREAK;
    END;

    -- 2. Up: new parents of anything in the closure.
    WHILE 1 = 1
    BEGIN
        INSERT INTO #Closure
        (
            StagedRowId,
            IsSeed,
            IsDownward
        )
        SELECT DISTINCT
            e.ParentStagedRowId,
            0,
            0
        FROM #Closure AS c
        INNER JOIN #Edges AS e
            ON e.ChildStagedRowId = c.StagedRowId
        INNER JOIN #Rows AS parentRow
            ON parentRow.StagedRowId = e.ParentStagedRowId
        WHERE parentRow.IsSelectable = 1
          AND parentRow.DifferenceType = N'Insert'
          AND parentRow.HasOverride = 0
          AND NOT EXISTS (SELECT 1 FROM #Closure AS existing WHERE existing.StagedRowId = e.ParentStagedRowId);

        IF @@ROWCOUNT = 0 BREAK;
    END;

    DECLARE dependency_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            r.RegistryGuid,
            r.SourceRowGuid,
            r.DifferenceType,
            sel.Guid
        FROM #Closure AS c
        INNER JOIN #Rows AS r
            ON r.StagedRowId = c.StagedRowId
        LEFT JOIN SMigration.Metadata_RunSelections AS sel
            ON sel.RunGuid = @RunGuid
           AND sel.RegistryGuid = r.RegistryGuid
           AND sel.SourceRowGuid = r.SourceRowGuid
        WHERE c.IsSeed = 0
          AND
          (
              sel.Guid IS NULL
              OR sel.RowStatus IN (0,254)
          );

    OPEN dependency_cursor;

    FETCH NEXT FROM dependency_cursor
    INTO @RegistryGuid, @SourceRowGuid, @DifferenceType, @SelectionGuid;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @SelectionGuid = ISNULL(@SelectionGuid, NEWID());

        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Metadata_RunSelections';

        IF EXISTS (SELECT 1 FROM SMigration.Metadata_RunSelections AS sel WHERE sel.Guid = @SelectionGuid)
        BEGIN
            UPDATE SMigration.Metadata_RunSelections
            SET
                RowStatus = 1,
                DifferenceType = @DifferenceType,
                SelectionSource = N'Dependency',
                SelectedByUserId = ISNULL(SCore.GetCurrentUserId(), -1),
                SelectedOnUtc = SYSUTCDATETIME()
            WHERE Guid = @SelectionGuid;
        END
        ELSE
        BEGIN
            INSERT INTO SMigration.Metadata_RunSelections
            (
                Guid,
                RowStatus,
                RunGuid,
                RegistryGuid,
                SourceRowGuid,
                DifferenceType,
                SelectionSource,
                SelectedByUserId,
                SelectedOnUtc
            )
            SELECT
                @SelectionGuid,
                1,
                @RunGuid,
                @RegistryGuid,
                @SourceRowGuid,
                @DifferenceType,
                N'Dependency',
                ISNULL(SCore.GetCurrentUserId(), -1),
                SYSUTCDATETIME();
        END;

        SET @AddedCount += 1;

        FETCH NEXT FROM dependency_cursor
        INTO @RegistryGuid, @SourceRowGuid, @DifferenceType, @SelectionGuid;
    END;

    CLOSE dependency_cursor;
    DEALLOCATE dependency_cursor;

    IF @AddedCount > 0
    BEGIN
        UPDATE SMigration.Metadata_Run
        SET
            RunStatus = N'Staged',
            ValidatedOnUtc = NULL
        WHERE Guid = @RunGuid
          AND RowStatus NOT IN (0,254);
    END;

    SELECT @AddedCount AS AutoSelectedCount;
END
GO

GO

/* Deploy StoredProcedure SMigration.MetadataRunSelection_Clear using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataRunSelection_Clear.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[MetadataRunSelection_Clear]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[MetadataRunSelection_Clear]
(
    @RunGuid UNIQUEIDENTIFIER,
    @SchemaName NVARCHAR(128) = N'',
    @TableName NVARCHAR(128) = N'',
    @DifferenceType NVARCHAR(30) = N''
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @SelectionsToClear TABLE
    (
        SelectionGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY
    );

    INSERT INTO @SelectionsToClear
    (
        SelectionGuid
    )
    SELECT
        sel.Guid
    FROM SMigration.Metadata_RunSelections AS sel
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sel.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    WHERE sel.RunGuid = @RunGuid
      AND sel.RowStatus NOT IN (0,254)
      AND (@SchemaName = N'' OR tr.SchemaName = @SchemaName)
      AND (@TableName = N'' OR tr.TableName = @TableName)
      AND (@DifferenceType = N'' OR sel.DifferenceType = @DifferenceType);

    DECLARE @SelectionGuid UNIQUEIDENTIFIER;

    DECLARE SelectionCursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            clearRows.SelectionGuid
        FROM @SelectionsToClear AS clearRows
        ORDER BY clearRows.SelectionGuid;

    OPEN SelectionCursor;
    FETCH NEXT FROM SelectionCursor INTO @SelectionGuid;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SCore.DeleteDataObject
            @Guid = @SelectionGuid;

        FETCH NEXT FROM SelectionCursor INTO @SelectionGuid;
    END;

    CLOSE SelectionCursor;
    DEALLOCATE SelectionCursor;

    UPDATE sel
    SET
        sel.RowStatus = 254,
        sel.SelectedByUserId = ISNULL(SCore.GetCurrentUserId(), -1),
        sel.SelectedOnUtc = SYSUTCDATETIME()
    FROM SMigration.Metadata_RunSelections AS sel
    INNER JOIN @SelectionsToClear AS clearRows
        ON clearRows.SelectionGuid = sel.Guid
    WHERE sel.RowStatus NOT IN (0,254);

    UPDATE SMigration.Metadata_Run
    SET
        RunStatus = N'Staged',
        ValidatedOnUtc = NULL
    WHERE Guid = @RunGuid
      AND RowStatus NOT IN (0,254);

    EXEC SMigration.MetadataExecutionLog_Add
        @RunGuid = @RunGuid,
        @StepName = N'SelectionClear',
        @StepStatus = N'Succeeded',
        @Message = N'Metadata migration run selection cleared.',
        @DetailsJson = N'{}';
END
GO

GO

/* Deploy StoredProcedure SMigration.MetadataRunSelection_Upsert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataRunSelection_Upsert.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[MetadataRunSelection_Upsert]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[MetadataRunSelection_Upsert]
(
    @RunGuid UNIQUEIDENTIFIER,
    @SchemaName NVARCHAR(128),
    @TableName NVARCHAR(128),
    @SourceRowGuid UNIQUEIDENTIFIER,
    @DifferenceType NVARCHAR(30) = N'',
    @IsSelected BIT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @RegistryGuid UNIQUEIDENTIFIER,
        @StagedDifferenceType NVARCHAR(30),
        @TargetDatabaseName SYSNAME,
        @SelectionGuid UNIQUEIDENTIFIER;

    SELECT
        @TargetDatabaseName = run.TargetDatabaseName
    FROM SMigration.Metadata_Run AS run
    WHERE run.Guid = @RunGuid
      AND run.RowStatus NOT IN (0,254);

    SELECT TOP (1)
        @RegistryGuid = tr.Guid,
        @StagedDifferenceType = sr.DifferenceType
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND tr.SchemaName = @SchemaName
      AND tr.TableName = @TableName
      AND sr.SourceRowGuid = @SourceRowGuid
      AND (@DifferenceType = N'' OR sr.DifferenceType = @DifferenceType);

    IF @RegistryGuid IS NULL
        THROW 52100, 'The selected metadata staged row was not found.', 1;

    IF @StagedDifferenceType NOT IN (N'Insert', N'Update') AND ISNULL(@IsSelected, 0) = 1
        THROW 52101, 'Only Insert and Update metadata rows can be selected for apply.', 1;

    IF ISNULL(@IsSelected, 0) = 1
       AND EXISTS
       (
           SELECT 1
           FROM SMigration.Metadata_IgnoredRecords AS ignored
           WHERE ignored.DatabaseName = @TargetDatabaseName
             AND ignored.RegistryGuid = @RegistryGuid
             AND ignored.SourceRowGuid = @SourceRowGuid
             AND ignored.RowStatus NOT IN (0,254)
       )
        THROW 52102, 'Ignored metadata records cannot be selected. Unignore the record before selecting it.', 1;

    SELECT TOP (1)
        @SelectionGuid = sel.Guid
    FROM SMigration.Metadata_RunSelections AS sel
    WHERE sel.RunGuid = @RunGuid
      AND sel.RegistryGuid = @RegistryGuid
      AND sel.SourceRowGuid = @SourceRowGuid;

    IF ISNULL(@IsSelected, 0) = 1
    BEGIN
        SET @SelectionGuid = ISNULL(@SelectionGuid, NEWID());

        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Metadata_RunSelections';

        IF EXISTS
        (
            SELECT 1
            FROM SMigration.Metadata_RunSelections AS sel
            WHERE sel.Guid = @SelectionGuid
        )
        BEGIN
            UPDATE SMigration.Metadata_RunSelections
            SET
                RowStatus = 1,
                DifferenceType = @StagedDifferenceType,
                SelectionSource = N'Manual',
                SelectedByUserId = ISNULL(SCore.GetCurrentUserId(), -1),
                SelectedOnUtc = SYSUTCDATETIME()
            WHERE Guid = @SelectionGuid;
        END
        ELSE
        BEGIN
            INSERT INTO SMigration.Metadata_RunSelections
            (
                Guid,
                RowStatus,
                RunGuid,
                RegistryGuid,
                SourceRowGuid,
                DifferenceType,
                SelectionSource,
                SelectedByUserId,
                SelectedOnUtc
            )
            SELECT
                @SelectionGuid,
                1,
                @RunGuid,
                @RegistryGuid,
                @SourceRowGuid,
                @StagedDifferenceType,
                N'Manual',
                ISNULL(SCore.GetCurrentUserId(), -1),
                SYSUTCDATETIME();
        END;
    END
    ELSE
    BEGIN
        IF @SelectionGuid IS NOT NULL
        BEGIN
            EXEC SCore.DeleteDataObject
                @Guid = @SelectionGuid;

            UPDATE SMigration.Metadata_RunSelections
            SET
                RowStatus = 254,
                SelectedByUserId = ISNULL(SCore.GetCurrentUserId(), -1),
                SelectedOnUtc = SYSUTCDATETIME()
            WHERE Guid = @SelectionGuid
              AND RowStatus NOT IN (0,254);
        END;
    END;

    UPDATE SMigration.Metadata_Run
    SET
        RunStatus = N'Staged',
        ValidatedOnUtc = NULL
    WHERE Guid = @RunGuid
      AND RowStatus NOT IN (0,254);
END
GO

GO

/* Deploy StoredProcedure SMigration.MetadataStage_NormaliseDifferences using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataStage_NormaliseDifferences.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SMigration.MetadataStage_NormaliseDifferences
    Source schema hash : 74529A02AEFEF9840D05B73F9C94A8AB8FDF6A93488264D6BDDB06F3D7449DD1
    Definition SHA-256 : 8DC4B17300CE90836E76C28E142652CC8691B949FE53EF8FA1AA48447E884E41

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
    CymBuild Metadata CI/CD
    Stage/Diff normalisation fix

    Purpose:
    - Keep raw SourcePayloadJson / TargetPayloadJson for audit.
    - Stop Stage/Diff reporting false inserts where Apply intentionally reuses
      an existing target row by natural key.
    - Stop Stage/Diff reporting false updates caused only by environment-specific
      numeric IDs/FKs.

    Required call point:
    - Execute SMigration.MetadataStage_NormaliseDifferences after all
      SMigration.Metadata_StagedRows have been inserted for a run and before
      SummaryJson is calculated/read by the UI.

    Works for:
    - same-server SQL proc staging
    - API two-connection staging, provided the API calls this proc after staging
*/

CREATE OR ALTER PROCEDURE [SMigration].[MetadataStage_NormaliseDifferences]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SMigration.Metadata_Run AS r
        WHERE r.Guid = @RunGuid
          AND r.RowStatus NOT IN (0,254)
    )
    BEGIN
        THROW 53000, 'Metadata stage normalisation failed because the run was not found or is inactive.', 1;
    END;

    DECLARE
        @EntityPropertiesColumnList NVARCHAR(MAX),
        @GridViewColumnDefinitionsColumnList NVARCHAR(MAX),
        @IconsColumnList NVARCHAR(MAX),
        @Sql NVARCHAR(MAX);

    /* =========================================================
       1. Convert false inserts to natural-key target matches.
          These remain Update/NoChange based on the real target payload.
       ========================================================= */

    SELECT
        @EntityPropertiesColumnList = STRING_AGG(CONVERT(NVARCHAR(MAX), N'epj.' + QUOTENAME(c.name)), N',')
            WITHIN GROUP (ORDER BY c.column_id)
    FROM sys.schemas AS s
    INNER JOIN sys.tables AS t
        ON t.schema_id = s.schema_id
    INNER JOIN sys.columns AS c
        ON c.object_id = t.object_id
    WHERE s.name = N'SCore'
      AND t.name = N'EntityProperties'
      AND c.is_computed = 0
      AND c.system_type_id <> 189;

    IF @EntityPropertiesColumnList IS NOT NULL
    BEGIN
        SET @Sql = N'
;WITH EntityPropertiesToNaturalise AS
(
    SELECT
        sr.ID AS StagedRowID,
        targetEp.ID AS TargetEntityPropertyID
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    OUTER APPLY
    (
        SELECT
            TRY_CONVERT(BIGINT, COALESCE
            (
                JSON_VALUE(sr.SourcePayloadJson, N''$.EntityHoBTID''),
                JSON_VALUE(sr.SourcePayloadJson, N''$.EntityHoBTId''),
                JSON_VALUE(sr.SourcePayloadJson, N''$.EntityHobtID''),
                JSON_VALUE(sr.SourcePayloadJson, N''$.EntityHobtId'')
            )) AS SourceEntityHoBTID,
            JSON_VALUE(sr.SourcePayloadJson, N''$.Name'') AS PropertyName
    ) AS parsed
    LEFT JOIN SMigration.Metadata_TableRegistry AS hobtReg
        ON hobtReg.SchemaName = N''SCore''
       AND hobtReg.TableName = N''EntityHobts''
       AND hobtReg.RowStatus NOT IN (0,254)
    LEFT JOIN SMigration.Metadata_StagedRows AS srcHobt
        ON srcHobt.RunGuid = sr.RunGuid
       AND srcHobt.RegistryGuid = hobtReg.Guid
       AND srcHobt.SourceRowId = parsed.SourceEntityHoBTID
       AND srcHobt.RowStatus NOT IN (0,254)
    LEFT JOIN SCore.EntityHobts AS targetHobt
        ON targetHobt.Guid = srcHobt.SourceRowGuid
       AND targetHobt.RowStatus NOT IN (0,254)
    LEFT JOIN SCore.EntityProperties AS targetEp
        ON targetEp.EntityHoBTID = targetHobt.ID
       AND targetEp.Name = parsed.PropertyName
       AND targetEp.RowStatus NOT IN (0,254)
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType = N''Insert''
      AND tr.SchemaName = N''SCore''
      AND tr.TableName = N''EntityProperties''
      AND targetEp.ID IS NOT NULL
)
UPDATE sr
SET
    TargetPayloadJson = tgt.TargetPayloadJson,
    TargetPayloadHash = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)),
    DifferenceType = CASE
        WHEN HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), sr.SourcePayloadJson))
           = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)) THEN N''NoChange''
        ELSE N''Update''
    END
FROM SMigration.Metadata_StagedRows AS sr
INNER JOIN EntityPropertiesToNaturalise AS n
    ON n.StagedRowID = sr.ID
OUTER APPLY
(
    SELECT
        (
            SELECT ' + @EntityPropertiesColumnList + N'
            FROM SCore.EntityProperties AS epj
            WHERE epj.ID = n.TargetEntityPropertyID
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        ) AS TargetPayloadJson
) AS tgt
WHERE tgt.TargetPayloadJson IS NOT NULL;';

        EXEC sys.sp_executesql
            @Sql,
            N'@RunGuid UNIQUEIDENTIFIER',
            @RunGuid = @RunGuid;
    END;

    SELECT
        @GridViewColumnDefinitionsColumnList = STRING_AGG(CONVERT(NVARCHAR(MAX), N'gvcdj.' + QUOTENAME(c.name)), N',')
            WITHIN GROUP (ORDER BY c.column_id)
    FROM sys.schemas AS s
    INNER JOIN sys.tables AS t
        ON t.schema_id = s.schema_id
    INNER JOIN sys.columns AS c
        ON c.object_id = t.object_id
    WHERE s.name = N'SUserInterface'
      AND t.name = N'GridViewColumnDefinitions'
      AND c.is_computed = 0
      AND c.system_type_id <> 189;

    IF @GridViewColumnDefinitionsColumnList IS NOT NULL
    BEGIN
        SET @Sql = N'
;WITH GridViewColumnsToNaturalise AS
(
    SELECT
        sr.ID AS StagedRowID,
        targetCol.ID AS TargetGridViewColumnDefinitionID
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    OUTER APPLY
    (
        SELECT
            TRY_CONVERT(BIGINT, COALESCE
            (
                JSON_VALUE(sr.SourcePayloadJson, N''$.GridViewDefinitionID''),
                JSON_VALUE(sr.SourcePayloadJson, N''$.GridViewDefinitionId'')
            )) AS SourceGridViewDefinitionID,
            JSON_VALUE(sr.SourcePayloadJson, N''$.Name'') AS ColumnName,
            TRY_CONVERT(BIT, JSON_VALUE(sr.SourcePayloadJson, N''$.IsPrimaryKey'')) AS IsPrimaryKey
    ) AS parsed
    LEFT JOIN SMigration.Metadata_TableRegistry AS gvdReg
        ON gvdReg.SchemaName = N''SUserInterface''
       AND gvdReg.TableName = N''GridViewDefinitions''
       AND gvdReg.RowStatus NOT IN (0,254)
    LEFT JOIN SMigration.Metadata_StagedRows AS srcGvd
        ON srcGvd.RunGuid = sr.RunGuid
       AND srcGvd.RegistryGuid = gvdReg.Guid
       AND srcGvd.SourceRowId = parsed.SourceGridViewDefinitionID
       AND srcGvd.RowStatus NOT IN (0,254)
    LEFT JOIN SUserInterface.GridViewDefinitions AS targetGvd
        ON targetGvd.Guid = srcGvd.SourceRowGuid
       AND targetGvd.RowStatus NOT IN (0,254)
    LEFT JOIN SUserInterface.GridViewColumnDefinitions AS targetCol
        ON targetCol.GridViewDefinitionID = targetGvd.ID
       AND targetCol.RowStatus NOT IN (0,254)
       AND
       (
            targetCol.Name = parsed.ColumnName
            OR
            (
                ISNULL(parsed.IsPrimaryKey, 0) = 1
                AND targetCol.IsPrimaryKey = 1
            )
       )
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType = N''Insert''
      AND tr.SchemaName = N''SUserInterface''
      AND tr.TableName = N''GridViewColumnDefinitions''
      AND targetCol.ID IS NOT NULL
)
UPDATE sr
SET
    TargetPayloadJson = tgt.TargetPayloadJson,
    TargetPayloadHash = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)),
    DifferenceType = CASE
        WHEN HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), sr.SourcePayloadJson))
           = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)) THEN N''NoChange''
        ELSE N''Update''
    END
FROM SMigration.Metadata_StagedRows AS sr
INNER JOIN GridViewColumnsToNaturalise AS n
    ON n.StagedRowID = sr.ID
OUTER APPLY
(
    SELECT
        (
            SELECT ' + @GridViewColumnDefinitionsColumnList + N'
            FROM SUserInterface.GridViewColumnDefinitions AS gvcdj
            WHERE gvcdj.ID = n.TargetGridViewColumnDefinitionID
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        ) AS TargetPayloadJson
) AS tgt
WHERE tgt.TargetPayloadJson IS NOT NULL;';

        EXEC sys.sp_executesql
            @Sql,
            N'@RunGuid UNIQUEIDENTIFIER',
            @RunGuid = @RunGuid;
    END;

    SELECT
        @IconsColumnList = STRING_AGG(CONVERT(NVARCHAR(MAX), N'ij.' + QUOTENAME(c.name)), N',')
            WITHIN GROUP (ORDER BY c.column_id)
    FROM sys.schemas AS s
    INNER JOIN sys.tables AS t
        ON t.schema_id = s.schema_id
    INNER JOIN sys.columns AS c
        ON c.object_id = t.object_id
    WHERE s.name = N'SUserInterface'
      AND t.name = N'Icons'
      AND c.is_computed = 0
      AND c.system_type_id <> 189;

    IF @IconsColumnList IS NOT NULL
    BEGIN
        SET @Sql = N'
;WITH IconsToNaturalise AS
(
    SELECT
        sr.ID AS StagedRowID,
        targetIcon.ID AS TargetIconID
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    OUTER APPLY
    (
        SELECT JSON_VALUE(sr.SourcePayloadJson, N''$.Name'') AS IconName
    ) AS parsed
    LEFT JOIN SUserInterface.Icons AS targetIcon
        ON targetIcon.Name = parsed.IconName
       AND targetIcon.RowStatus NOT IN (0,254)
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType = N''Insert''
      AND tr.SchemaName = N''SUserInterface''
      AND tr.TableName = N''Icons''
      AND targetIcon.ID IS NOT NULL
)
UPDATE sr
SET
    TargetPayloadJson = tgt.TargetPayloadJson,
    TargetPayloadHash = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)),
    DifferenceType = CASE
        WHEN HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), sr.SourcePayloadJson))
           = HASHBYTES(''SHA2_256'', CONVERT(VARBINARY(MAX), tgt.TargetPayloadJson)) THEN N''NoChange''
        ELSE N''Update''
    END
FROM SMigration.Metadata_StagedRows AS sr
INNER JOIN IconsToNaturalise AS n
    ON n.StagedRowID = sr.ID
OUTER APPLY
(
    SELECT
        (
            SELECT ' + @IconsColumnList + N'
            FROM SUserInterface.Icons AS ij
            WHERE ij.ID = n.TargetIconID
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        ) AS TargetPayloadJson
) AS tgt
WHERE tgt.TargetPayloadJson IS NOT NULL;';

        EXEC sys.sp_executesql
            @Sql,
            N'@RunGuid UNIQUEIDENTIFIER',
            @RunGuid = @RunGuid;
    END;

    /* =========================================================
       2. Normalise false updates caused by environment-specific IDs.
          CYB-564: a foreign key column is no longer simply dropped from the comparison -
          that hid every genuine re-point (e.g. an EntityQueryParameters row re-mapped to a
          different EntityProperty staged as NoChange and was never applied). A declared,
          single-column FK to another enabled registered table is compared by the Guid each
          side's ID resolves to: on the source side the same Guid Apply will write (manual
          Identity Map override, then natural-key match, then the source row's own Guid - the
          #MetadataSourceGuidLookup order in MetadataApply_Run), on the target side the
          referenced target row's own Guid. When either side cannot be resolved the column
          falls back to the previous behaviour (ignored if it is in the legacy ID list, else
          compared as-is); two identical sentinel values (<= 0, e.g. -1) always compare equal.
          This also absorbs the per-table rules MetadataStage_NormaliseEnvironmentOnlyUpdates
          used to apply (Guid on naturalised rows, EntityQueries.Statement whitespace), which
          compared raw FK IDs and would otherwise undo the resolution above.
          Raw payloads remain available for audit.
       ========================================================= */

    DECLARE
        @NormaliseTargetDatabaseName SYSNAME,
        @RefRegistryGuid UNIQUEIDENTIFIER,
        @RefSchemaName SYSNAME,
        @RefTableName SYSNAME,
        @RefGuidColumnName SYSNAME,
        @RefPrimaryKeyColumnName SYSNAME;

    SELECT
        @NormaliseTargetDatabaseName = r.TargetDatabaseName
    FROM SMigration.Metadata_Run AS r
    WHERE r.Guid = @RunGuid
      AND r.RowStatus NOT IN (0,254);

    -- The ID columns the previous version ignored outright, spelled exactly as before. They are
    -- now only the fallback for a column that cannot be resolved by Guid (see header).
    DECLARE @LegacyIgnoredKeys TABLE
    (
        KeyName NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL
    );

    INSERT INTO @LegacyIgnoredKeys (KeyName)
    VALUES
        (N'EntityTypeID'), (N'EntityTypeId'),
        (N'EntityHoBTID'), (N'EntityHoBTId'), (N'EntityHobtID'), (N'EntityHobtId'),
        (N'LanguageLabelID'), (N'LanguageLabelId'),
        (N'LanguageID'), (N'LanguageId'),
        (N'EntityDataTypeID'), (N'EntityDataTypeId'),
        (N'EntityPropertyGroupID'), (N'EntityPropertyGroupId'),
        (N'DropDownListDefinitionID'), (N'DropDownListDefinitionId'),
        (N'EntityQueryID'), (N'EntityQueryId'),
        (N'MappedEntityPropertyID'), (N'MappedEntityPropertyId'),
        (N'GridDefinitionID'), (N'GridDefinitionId'),
        (N'GridViewDefinitionID'), (N'GridViewDefinitionId'),
        (N'MetricTypeID'), (N'MetricTypeId'),
        (N'DrawerIconID'), (N'DrawerIconId'),
        (N'GridViewTypeID'), (N'GridViewTypeId'),
        (N'IconID'), (N'IconId'),
        (N'PropertyGroupLayoutID'), (N'PropertyGroupLayoutId');

    IF OBJECT_ID(N'tempdb..#MetadataFkColumns') IS NOT NULL
        DROP TABLE #MetadataFkColumns;

    CREATE TABLE #MetadataFkColumns
    (
        ChildRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        ColumnName NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL,
        RefRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        RefGuidColumnName SYSNAME NOT NULL,
        CONSTRAINT PK_MetadataFkColumns PRIMARY KEY CLUSTERED (ChildRegistryGuid, ColumnName)
    );

    ;WITH DeclaredForeignKeys AS
    (
        SELECT
            childTr.Guid AS ChildRegistryGuid,
            pc.name AS ColumnName,
            refTr.Guid AS RefRegistryGuid,
            refTr.GuidColumnName AS RefGuidColumnName,
            COUNT(1) OVER (PARTITION BY childTr.Guid, pc.name) AS ForeignKeysOnColumn
        FROM SMigration.Metadata_TableRegistry AS childTr
        INNER JOIN sys.foreign_key_columns AS fkc
            ON fkc.parent_object_id = OBJECT_ID(QUOTENAME(childTr.SchemaName) + N'.' + QUOTENAME(childTr.TableName))
        INNER JOIN sys.columns AS pc
            ON pc.object_id = fkc.parent_object_id
           AND pc.column_id = fkc.parent_column_id
        INNER JOIN sys.tables AS rt
            ON rt.object_id = fkc.referenced_object_id
        INNER JOIN sys.schemas AS rs
            ON rs.schema_id = rt.schema_id
        INNER JOIN sys.columns AS rc
            ON rc.object_id = fkc.referenced_object_id
           AND rc.column_id = fkc.referenced_column_id
        INNER JOIN SMigration.Metadata_TableRegistry AS refTr
            ON refTr.SchemaName = rs.name
           AND refTr.TableName = rt.name
           AND refTr.RowStatus NOT IN (0,254)
           AND refTr.IsEnabled = 1
        WHERE childTr.RowStatus NOT IN (0,254)
          AND childTr.IsEnabled = 1
          AND pc.name <> N'RowStatus'
          AND rc.name = refTr.PrimaryKeyColumnName
          AND NOT EXISTS
          (
              SELECT 1
              FROM sys.foreign_key_columns AS otherColumn
              WHERE otherColumn.constraint_object_id = fkc.constraint_object_id
                AND otherColumn.constraint_column_id <> fkc.constraint_column_id
          )
    )
    INSERT INTO #MetadataFkColumns
    (
        ChildRegistryGuid,
        ColumnName,
        RefRegistryGuid,
        RefGuidColumnName
    )
    SELECT
        dfk.ChildRegistryGuid,
        dfk.ColumnName,
        dfk.RefRegistryGuid,
        dfk.RefGuidColumnName
    FROM DeclaredForeignKeys AS dfk
    WHERE dfk.ForeignKeysOnColumn = 1;

    IF OBJECT_ID(N'tempdb..#MetadataTargetIdGuid') IS NOT NULL
        DROP TABLE #MetadataTargetIdGuid;

    CREATE TABLE #MetadataTargetIdGuid
    (
        RefRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        ID BIGINT NOT NULL,
        RowGuid UNIQUEIDENTIFIER NOT NULL,
        CONSTRAINT PK_MetadataTargetIdGuid PRIMARY KEY CLUSTERED (RefRegistryGuid, ID)
    );

    -- This procedure runs in the target database (both staging paths call it there), so the
    -- referenced tables are read directly.
    DECLARE referenced_table_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT
            refTr.Guid,
            refTr.SchemaName,
            refTr.TableName,
            refTr.GuidColumnName,
            refTr.PrimaryKeyColumnName
        FROM #MetadataFkColumns AS fk
        INNER JOIN SMigration.Metadata_TableRegistry AS refTr
            ON refTr.Guid = fk.RefRegistryGuid
        WHERE OBJECT_ID(QUOTENAME(refTr.SchemaName) + N'.' + QUOTENAME(refTr.TableName)) IS NOT NULL;

    OPEN referenced_table_cursor;

    FETCH NEXT FROM referenced_table_cursor
    INTO @RefRegistryGuid, @RefSchemaName, @RefTableName, @RefGuidColumnName, @RefPrimaryKeyColumnName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @Sql = N'
INSERT INTO #MetadataTargetIdGuid
(
    RefRegistryGuid,
    ID,
    RowGuid
)
SELECT
    @RefRegistryGuid,
    TRY_CONVERT(BIGINT, t.' + QUOTENAME(@RefPrimaryKeyColumnName) + N'),
    CONVERT(UNIQUEIDENTIFIER, t.' + QUOTENAME(@RefGuidColumnName) + N')
FROM ' + QUOTENAME(@RefSchemaName) + N'.' + QUOTENAME(@RefTableName) + N' AS t
WHERE TRY_CONVERT(BIGINT, t.' + QUOTENAME(@RefPrimaryKeyColumnName) + N') IS NOT NULL
  AND t.' + QUOTENAME(@RefGuidColumnName) + N' IS NOT NULL;';

        EXEC sys.sp_executesql
            @Sql,
            N'@RefRegistryGuid UNIQUEIDENTIFIER',
            @RefRegistryGuid = @RefRegistryGuid;

        FETCH NEXT FROM referenced_table_cursor
        INTO @RefRegistryGuid, @RefSchemaName, @RefTableName, @RefGuidColumnName, @RefPrimaryKeyColumnName;
    END;

    CLOSE referenced_table_cursor;
    DEALLOCATE referenced_table_cursor;

    IF OBJECT_ID(N'tempdb..#MetadataSourceIdGuid') IS NOT NULL
        DROP TABLE #MetadataSourceIdGuid;

    CREATE TABLE #MetadataSourceIdGuid
    (
        RefRegistryGuid UNIQUEIDENTIFIER NOT NULL,
        SourceRowId BIGINT NOT NULL,
        ResolvedGuid UNIQUEIDENTIFIER NOT NULL,
        CONSTRAINT PK_MetadataSourceIdGuid PRIMARY KEY CLUSTERED (RefRegistryGuid, SourceRowId)
    );

    INSERT INTO #MetadataSourceIdGuid
    (
        RefRegistryGuid,
        SourceRowId,
        ResolvedGuid
    )
    SELECT
        sr.RegistryGuid,
        sr.SourceRowId,
        COALESCE
        (
            ov.TargetRowGuid,
            TRY_CONVERT(UNIQUEIDENTIFIER, JSON_VALUE(sr.TargetPayloadJson, N'$.' + tr.GuidColumnName)),
            sr.SourceRowGuid
        )
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    LEFT JOIN SMigration.Metadata_IdentityMapOverrides AS ov
        ON ov.DatabaseName = @NormaliseTargetDatabaseName
       AND ov.RegistryGuid = sr.RegistryGuid
       AND ov.SourceRowGuid = sr.SourceRowGuid
       AND ov.RowStatus NOT IN (0,254)
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.SourceRowId IS NOT NULL
      AND sr.SourceRowGuid IS NOT NULL
      AND EXISTS
      (
          SELECT 1
          FROM #MetadataFkColumns AS fk
          WHERE fk.RefRegistryGuid = sr.RegistryGuid
      );

    IF OBJECT_ID(N'tempdb..#MetadataRowsWithRealDifference') IS NOT NULL
        DROP TABLE #MetadataRowsWithRealDifference;

    CREATE TABLE #MetadataRowsWithRealDifference
    (
        StagedRowID BIGINT NOT NULL PRIMARY KEY
    );

    ;WITH Pairs AS
    (
        SELECT
            sr.ID AS StagedRowID,
            sr.RegistryGuid,
            tr.SchemaName,
            tr.TableName,
            kv.KeyName,
            kv.SourceValue,
            kv.TargetValue,
            -- TRY_CONVERT(BIGINT, ...) on an nvarchar(max) value over 8000 bytes (e.g. a long
            -- EntityQueries.Statement) raises 8152 instead of returning NULL. No ID is longer
            -- than 20 characters, so only short values are converted; CONVERT to NVARCHAR(20)
            -- truncates silently, which keeps this safe even if evaluated before the LEN guard.
            TRY_CONVERT(BIGINT, CASE WHEN LEN(kv.SourceValue) <= 20 THEN CONVERT(NVARCHAR(20), kv.SourceValue) END) AS SourceIdValue,
            TRY_CONVERT(BIGINT, CASE WHEN LEN(kv.TargetValue) <= 20 THEN CONVERT(NVARCHAR(20), kv.TargetValue) END) AS TargetIdValue
        FROM SMigration.Metadata_StagedRows AS sr
        INNER JOIN SMigration.Metadata_TableRegistry AS tr
            ON tr.Guid = sr.RegistryGuid
           AND tr.RowStatus NOT IN (0,254)
        CROSS APPLY
        (
            SELECT
                COALESCE(src.[key], tgt.[key]) COLLATE DATABASE_DEFAULT AS KeyName,
                src.[value] AS SourceValue,
                tgt.[value] AS TargetValue
            FROM OPENJSON(sr.SourcePayloadJson) AS src
            FULL OUTER JOIN OPENJSON(sr.TargetPayloadJson) AS tgt
                ON tgt.[key] COLLATE DATABASE_DEFAULT = src.[key] COLLATE DATABASE_DEFAULT
        ) AS kv
        WHERE sr.RunGuid = @RunGuid
          AND sr.RowStatus NOT IN (0,254)
          AND sr.DifferenceType = N'Update'
          AND sr.TargetPayloadJson IS NOT NULL
    ),
    Classified AS
    (
        SELECT
            p.StagedRowID,
            CASE
                WHEN p.KeyName = N'ID' THEN 0
                -- A row naturalised onto a different-Guid target row (step 1) legitimately
                -- differs by Guid on these tables.
                WHEN p.KeyName = N'Guid'
                     AND
                     (
                         (p.SchemaName = N'SCore' AND p.TableName IN (N'EntityProperties', N'EntityQueries'))
                         OR (p.SchemaName = N'SUserInterface' AND p.TableName = N'GridViewColumnDefinitions')
                     ) THEN 0
                WHEN p.KeyName = N'Statement' AND p.SchemaName = N'SCore' AND p.TableName = N'EntityProperties' THEN 0
                WHEN p.KeyName = N'Statement' AND p.SchemaName = N'SCore' AND p.TableName = N'EntityQueries' THEN
                    CASE
                        WHEN LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(p.SourceValue, N''), CHAR(13), N''), CHAR(10), N''), CHAR(9), N''), NCHAR(160), N''), N' ', N''), N'"', N''))
                           = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(p.TargetValue, N''), CHAR(13), N''), CHAR(10), N''), CHAR(9), N''), NCHAR(160), N''), N' ', N''), N'"', N'')) THEN 0
                        ELSE 1
                    END
                WHEN fk.ColumnName IS NOT NULL
                     AND CONVERT(VARBINARY(MAX), p.SourceValue) = CONVERT(VARBINARY(MAX), p.TargetValue)
                     AND p.SourceIdValue <= 0 THEN 0
                WHEN fk.ColumnName IS NOT NULL
                     AND srcRef.ResolvedGuid IS NOT NULL
                     AND tgtRef.RowGuid IS NOT NULL THEN
                    CASE WHEN srcRef.ResolvedGuid = tgtRef.RowGuid THEN 0 ELSE 1 END
                WHEN legacy.KeyName IS NOT NULL THEN 0
                WHEN p.SourceValue IS NULL AND p.TargetValue IS NULL THEN 0
                WHEN CONVERT(VARBINARY(MAX), p.SourceValue) = CONVERT(VARBINARY(MAX), p.TargetValue) THEN 0
                ELSE 1
            END AS IsDifferent
        FROM Pairs AS p
        LEFT JOIN #MetadataFkColumns AS fk
            ON fk.ChildRegistryGuid = p.RegistryGuid
           AND fk.ColumnName = p.KeyName
        LEFT JOIN #MetadataSourceIdGuid AS srcRef
            ON srcRef.RefRegistryGuid = fk.RefRegistryGuid
           AND srcRef.SourceRowId = p.SourceIdValue
        LEFT JOIN #MetadataTargetIdGuid AS tgtRef
            ON tgtRef.RefRegistryGuid = fk.RefRegistryGuid
           AND tgtRef.ID = p.TargetIdValue
        OUTER APPLY
        (
            SELECT TOP (1) lk.KeyName
            FROM @LegacyIgnoredKeys AS lk
            WHERE lk.KeyName = p.KeyName
        ) AS legacy
    )
    INSERT INTO #MetadataRowsWithRealDifference
    (
        StagedRowID
    )
    SELECT DISTINCT
        c.StagedRowID
    FROM Classified AS c
    WHERE c.IsDifferent = 1;

    UPDATE sr
    SET DifferenceType = N'NoChange'
    FROM SMigration.Metadata_StagedRows AS sr
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType = N'Update'
      AND sr.TargetPayloadJson IS NOT NULL
      AND NOT EXISTS
      (
          SELECT 1
          FROM #MetadataRowsWithRealDifference AS diff
          WHERE diff.StagedRowID = sr.ID
      );

    /* =========================================================
       3. Refresh run summary after normalisation.
       ========================================================= */

    UPDATE SMigration.Metadata_Run
    SET SummaryJson =
    (
        SELECT
            CONCAT
            (
                N'{"insertCount":',
                CONVERT(NVARCHAR(30), ISNULL(SUM(CASE WHEN sr.DifferenceType = N'Insert' THEN 1 ELSE 0 END), 0)),
                N',"updateCount":',
                CONVERT(NVARCHAR(30), ISNULL(SUM(CASE WHEN sr.DifferenceType = N'Update' THEN 1 ELSE 0 END), 0)),
                N',"noChangeCount":',
                CONVERT(NVARCHAR(30), ISNULL(SUM(CASE WHEN sr.DifferenceType = N'NoChange' THEN 1 ELSE 0 END), 0)),
                N',"totalCount":',
                CONVERT(NVARCHAR(30), COUNT_BIG(1)),
                N'}'
            )
        FROM SMigration.Metadata_StagedRows AS sr
        WHERE sr.RunGuid = @RunGuid
          AND sr.RowStatus NOT IN (0,254)
    )
    WHERE Guid = @RunGuid
      AND RowStatus NOT IN (0,254);
END;
GO

