                    CONVERT(NVARCHAR(50), ISNULL(t.LegacySystemID, -1)) AS LegacySystemID
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            ),
            DifferingColumnsJson = COALESCE
            (
