        FROM SMigration.Onboarding_Contacts AS s
        LEFT JOIN SCrm.Contacts AS t
            ON t.Guid = s.ContactGuid
        LEFT JOIN SCrm.Accounts AS account
            ON account.ID = t.PrimaryAccountID
        LEFT JOIN SCrm.Addresses AS address
