                     AND ISNULL(t.IncludeSchedule, 0) = s.IncludeSchedule
                     AND ISNULL(t.IncludeDueDate, 0) = s.IncludeDueDate
                     AND ISNULL(t.HasExternalSubmission, 0) = s.HasExternalSubmission
                    THEN N'Same'
                    ELSE N'Different'
                END,
            SourceValuesJson =
