           ======================================================================================== */
        ;WITH SourceJtat AS
        (
            SELECT
                s.JobTypeActivityTypeGuid,
                s.RowStatus,
                jt.ID AS JobTypeID,
                at.ID AS ActivityTypeID,
                ROW_NUMBER() OVER
                (
