           AND t.ActivityTypeID = at.ID
           AND t.RowStatus NOT IN (0, 254)
        WHERE s.RunGuid = @RunGuid
          AND s.JobTypeActivityTypeGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SJob.JobTypeActivityTypes AS x
              WHERE x.Guid = s.JobTypeActivityTypeGuid
                AND x.ID > 0
          )
          AND NOT EXISTS
          (
