            WHERE s.RunGuid = @RunGuid
              AND s.JobTypeActivityTypeGuid = @Guid
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM SJob.JobTypeActivityTypes AS x
                  WHERE x.JobTypeID = jt.ID
                    AND x.ActivityTypeID = at.ID
