    INNER JOIN ' + QUOTENAME(@SourceDatabase) + N'.SJob.JobTypes AS jt
        ON jt.ID = jtat.JobTypeID
    INNER JOIN ' + QUOTENAME(@SourceDatabase) + N'.SJob.ActivityTypes AS at
